    const peerLines = peers.length === 0 ? "" : "<p><em>Peers</em></p><p>" + peers.join(", ") + "</p>";
    const connLines = connections.length === 0 ? "" : "<p><em>Connections</em></p><p>" + connections.map((c) => `${c.fromPeerId} → ${c.toPeerId}${c.transportType ? ` (${c.transportType})` : ""}${c.connected ? "" : " [disconnected]"}`).join("<br/>") + "</p>";
