function attachToggleListeners(container, runtime) {
    container.querySelectorAll(".devtools-disable").forEach((btn) => {
        const name = btn.dataset.name;
        if (name) {
            btn.onclick = () => {
                runtime.modules.disable(name);
                if (runtime.devtools) {
                    runtime.devtools.activeModules = runtime.modules.getActiveNames();
                    runtime.devtools.inactiveModules = runtime.modules.getInactiveNames();
                    runtime.devtools.pipelineGraph = runtime.pipeline?.getGraph() ?? [];
                }
                renderDevTools(runtime.devtools, runtime);
            };
        }
    });
    container.querySelectorAll(".devtools-enable").forEach((btn) => {
        const name = btn.dataset.name;
        if (name) {
            btn.onclick = () => {
                runtime.modules.enable(name);
                if (runtime.devtools) {
                    runtime.devtools.activeModules = runtime.modules.getActiveNames();
                    runtime.devtools.inactiveModules = runtime.modules.getInactiveNames();
                    runtime.devtools.pipelineGraph = runtime.pipeline?.getGraph() ?? [];
                }
                renderDevTools(runtime.devtools, runtime);
            };
        }
    });
}
function renderDevTools(data, runtime) {
    const container = ensureContainer();
    if (!container)
        return;
    const activeModules = data.activeModules ?? [];
    const inactiveModules = data.inactiveModules ?? [];
    const transportModeSuffix = data.transportMode === "bootstrap" ? ` (${data.transportMode})` : "";
    const transportLine = data.activeTransport != null
        ? `<p><strong>Transport</strong>: ${data.activeTransport}${transportModeSuffix}</p>`
        : "<p><strong>Transport</strong>: none</p>";
    const bootstrapPeersLine = (data.bootstrapPeers?.length ?? 0) > 0
        ? `<p><strong>Bootstrap peers</strong>: ${data.bootstrapPeers.join(", ")}</p>`
        : data.transportMode === "bootstrap"
            ? "<p><strong>Bootstrap peers</strong>: none yet</p>"
            : "";
    const meshLine = (data.meshConnections?.length ?? 0) > 0
        ? `<p><strong>Mesh connections</strong>: ${data.meshConnections.join(" ↔ ")}</p>`
        : "";
    const bootstrapSignalingLine = data.bootstrapSignalingMode != null
        ? `<p><strong>Bootstrap signaling</strong>: ${data.bootstrapSignalingMode} (${data.bootstrapSignalingMode === "websocket" ? "cross-browser" : data.bootstrapSignalingMode === "invite" ? "invite link" : "same-tab"})</p>`
        : "";
    const bootstrapSourcesLine = data.bootstrapPeerSources && Object.keys(data.bootstrapPeerSources).length > 0
        ? `<p><strong>Peer sources</strong>: ${Object.entries(data.bootstrapPeerSources)
            .map(([id, src]) => `${id}=${src}`)
            .join(", ")}</p>`
        : "";
    const roomLine = data.roomTopology != null || data.peerCount != null
        ? `<p><strong>Room</strong>: topology ${data.roomTopology ?? "-"} | peers ${data.peerCount ?? 0}</p>`
        : "";
    const uiZonesLine = runtime ? renderUIZones(runtime) : "";
    const streamGraphViewerLine = runtime ? renderStreamGraphViewer(runtime) : "";
    const peerTopologyLine = runtime ? renderPeerTopologyViewer(runtime) : "";
    const pipelineOrderLine = runtime ? renderPipelineOrderViewer(runtime) : "";
    const architectureDiagnosticsLine = runtime ? renderArchitectureDiagnostics(runtime) : "";
    const runtimeTimelineLine = runtime ? renderRuntimeTimelinePanel(runtime) : "";
    container.innerHTML = [
        "<div class='devtools-output'>",
        renderModules(data.modules),
        runtimeTimelineLine,
        renderModuleManifests(data.moduleManifests),
        architectureDiagnosticsLine,
        uiZonesLine,
        roomLine,
        transportLine,
        bootstrapPeersLine,
        meshLine,
        bootstrapSignalingLine,
        bootstrapSourcesLine,
        peerTopologyLine,
        renderActiveModules(activeModules, runtime),
        renderInactiveModules(inactiveModules, runtime),
        renderStreamList(data.streams),
        renderGraph(data.graph),
        renderPipelineGraph(data.pipelineGraph),
        renderPipelineGraphFromManifests(data.pipelineGraphFromManifests),
        pipelineOrderLine,
        streamGraphViewerLine,
        "</div>",
    ].join("");
    if (runtime) {
        attachToggleListeners(container, runtime);
        attachExportReportListener(container, runtime);
        attachTimelineListeners(container, runtime);
    }
}
function attachExportReportListener(container, runtime) {
    const btn = container.querySelector(".devtools-export-architecture-report");
    if (!btn)
        return;
    btn.onclick = () => {
        const guardian = runtime.services?.get("architectureGuardian");
        if (!guardian)
            return;
        const report = guardian.getArchitectureReport();
        const blob = new Blob([JSON.stringify(report, null, 2)], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = "ArchitectureReport.json";
        a.click();
        URL.revokeObjectURL(url);
    };
}
function getDevToolsContainerId() {
    return CONTAINER_ID;
}
