/**
 * Bridge: subscribes to invite:create, calls startBootstrapInviteHost + addLink, emits invite:created.
 * Ref: module-system.mdc, stream-graph.mdc (event-driven).
 */
import { useEffect } from "react";
import { useRuntime } from "./RuntimeContext";
import { startBootstrapInviteHost } from "@grstream/bootstrap-invite";
const INVITE_CREATE = "invite:create";
const INVITE_CREATED = "invite:created";
const INVITE_CREATE_ERROR = "invite:create-error";
export function InviteCreateBridge() {
    const runtime = useRuntime();
    useEffect(() => {
        if (!runtime?.services)
            return;
        if (typeof window !== "undefined") {
            window.__GRS_RUNTIME__ = runtime;
        }
        const off = runtime.events.on(INVITE_CREATE, () => {
            if (typeof window !== "undefined" && process.env?.NODE_ENV === "development") {
                console.log("[Bridge] received invite:create");
            }
            (async () => {
                try {
                    const api = runtime.services?.get("peerBootstrap");
                    if (!api?.createInvite) {
                        runtime.events.emit(INVITE_CREATE_ERROR, {
                            message: "Режим приглашения недоступен. Войдите в комнату по кнопке «Создать комнату (приглашение-ссылка)».",
                        });
                        return;
                    }
                    const result = await startBootstrapInviteHost(runtime);
                    const inviteLinks = runtime.services?.get("inviteLinks");
                    inviteLinks?.addLink?.({
                        inviteId: result.inviteId,
                        url: result.url,
                        token: result.token,
                    });
                    runtime.events.emit(INVITE_CREATED, result);
                    if (typeof window !== "undefined" && process.env?.NODE_ENV === "development") {
                        console.log("[Bridge] emitting invite:created", result);
                    }
                }
                catch (e) {
                    const raw = e instanceof Error ? e.message : "Create invite failed";
                    const message = raw.includes("invite mode") || raw.includes("only in invite")
                        ? "Сначала войдите по кнопке «Создать комнату (приглашение-ссылка)»."
                        : raw;
                    runtime.events.emit(INVITE_CREATE_ERROR, { message });
                    if (typeof window !== "undefined" && process.env?.NODE_ENV === "development") {
                        console.log("[Bridge] emitting invite:create-error", message);
                    }
                }
            })();
        });
        return () => {
            off();
        };
    }, [runtime]);
    return null;
}
