/**
 * Client-side runtime event logger. Subscribes to key GRS events for debugging.
 *
 * Уровень логирования (localStorage, до `attachRuntimeLogger`):
 * - `GRS_RUNTIME_LOG` = `off` | `0` — не подписываться вообще.
 * - `GRS_RUNTIME_LOG` = `all` | `verbose` — все события из списка, включая частые stream:*.
 * - иначе — «тихий» режим: без `stream:created` / `stream:processing` / `stream:processed` (меньше шума в консоли).
 *
 * Примечание: шум от повторных `stream:created` также снижен стабильными `id` в publish (peer-bootstrap, video-stream, screen share).
 */
const LOG_PREFIX = "[GRS]";
const NOISY_STREAM_EVENTS = new Set(["stream:created", "stream:processing", "stream:processed"]);
const EVENTS = [
    "stream:created",
    "stream:processing",
    "stream:processed",
    "stream:error",
    "module:loading",
    "module:initialized",
    "module:error",
    "module:dependency-missing",
    "module:cycle-detected",
    "stream:node-registered",
    "stream:graph-updated",
    "bootstrap:joined",
    "bootstrap:leave",
    "bootstrap:host-start",
    "bootstrap:offer-created",
    "bootstrap:offer-sent",
    "bootstrap:answer-received",
    "bootstrap:peer-connected",
    "bootstrap:peer-disconnected",
    "bootstrap:negotiation-error",
    "bootstrap:connection-failed",
    "invite:create",
    "invite:created",
    "invite:create-error",
    "room:leave",
    "room:invite:create",
    "room:invite:join",
    "room:invite:answer",
    "room:invite:generate-answer",
    "room:invite:revoke",
    "room:screen:start",
    "room:screen:stop",
];
function resolveEventsToSubscribe() {
    if (typeof localStorage === "undefined") {
        return EVENTS.filter((e) => !NOISY_STREAM_EVENTS.has(e));
    }
    const mode = localStorage.getItem("GRS_RUNTIME_LOG")?.trim().toLowerCase() ?? "";
    if (mode === "off" || mode === "0" || mode === "false") {
        return [];
    }
    if (mode === "all" || mode === "verbose") {
        return [...EVENTS];
    }
    return EVENTS.filter((e) => !NOISY_STREAM_EVENTS.has(e));
}
export function attachRuntimeLogger(runtime) {
    const names = resolveEventsToSubscribe();
    if (names.length === 0) {
        return () => { };
    }
    const unsubs = names.map((event) => runtime.events.on(event, (payload) => {
        if (typeof console?.log === "function") {
            console.log(`${LOG_PREFIX} ${event}`, payload !== undefined ? payload : "");
        }
    }));
    return () => unsubs.forEach((off) => off());
}
